type Delta =
  | { type: "text_delta"; text: string }
  | { type: "input_json_delta"; partial_json: string };

type StreamEvent =
  | { type: "message_start"; message: { id: string } }
  | { type: "content_block_start"; index: number; content_block:
      | { type: "text"; text: string }
      | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> } }
  | { type: "content_block_delta"; index: number; delta: Delta }
  | { type: "content_block_stop"; index: number }
  | { type: "message_delta"; delta: { stop_reason: string | null }; usage: { output_tokens: number } }
  | { type: "message_stop" }
  | { type: "ping" };

type ToolCall = { id: string; name: string; args: unknown };
type ChatState =
  | { status: "idle" }
  | { status: "streaming"; text: string; toolCalls: ToolCall[] }
  | { status: "done"; text: string; toolCalls: ToolCall[]; stopReason: string | null };

// черновик по каждому tool_use-блоку: сюда копятся куски JSON, ключ — index блока
const pending = new Map<number, { id: string; name: string; json: string }>();

function reduce(state: ChatState, ev: StreamEvent): ChatState {
  switch (ev.type) {
    case "message_start":
      return { status: "streaming", text: "", toolCalls: [] };
    case "content_block_start":
      if (ev.content_block.type === "tool_use") {
        pending.set(ev.index, { id: ev.content_block.id, name: ev.content_block.name, json: "" });
      }
      return state;
    case "content_block_delta": {
      if (state.status !== "streaming") return state;
      const d = ev.delta;
      switch (d.type) {
        case "text_delta":
          return { ...state, text: state.text + d.text };   // d.text есть только здесь
        case "input_json_delta": {
          const p = pending.get(ev.index);
          if (p) p.json += d.partial_json;                    // копим, парсить рано
          return state;
        }
        default: {
          const _never: never = d;
          console.warn("unknown delta", (_never as { type?: string }).type);
          return state;
        }
      }
    }
    case "content_block_stop": {
      const p = pending.get(ev.index);
      if (!p || state.status !== "streaming") return state;
      pending.delete(ev.index);
      let parsed: unknown;
      try { parsed = JSON.parse(p.json || "{}"); } catch { parsed = undefined; }
      const r = SearchArgs.safeParse(parsed);               // схема из предыдущего раздела
      const args = r.success ? r.data : { invalid: true, issues: r.error.issues };
      return { ...state, toolCalls: [...state.toolCalls, { id: p.id, name: p.name, args }] };
    }
    case "message_delta":
      if (state.status !== "streaming") return state;
      return { status: "done", text: state.text, toolCalls: state.toolCalls, stopReason: ev.delta.stop_reason };
    case "message_stop":
    case "ping":
      return state;
    default: {
      const _never: never = ev;                              // полнота при компиляции
      console.warn("unknown event", (_never as { type?: string }).type); // в runtime: лог и пропуск
      return state;
    }
  }
}

